contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(amount == 10, "must send exactly one ticket price");
        require(address(this).balance >= amount, "not enough balance");

        address bankBefore = c.bank(); if (__ESBMC_reverted()) return;
        uint totalBefore = address(c).balance + c.bank().balance;

        bool reverted;
        c.play{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        address bankAfter = c.bank(); if (__ESBMC_reverted()) return;
        uint totalAfter = address(c).balance + c.bank().balance;

        assert(!reverted || (bankAfter == bankBefore && totalAfter >= totalBefore));
    }

    receive() external payable {}
}

