contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    EtherLotto c;

    function setUp() public {
        c = new EtherLotto();
    }

    function _run(uint256 amount) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        amount = 10;
        vm.assume(address(this).balance >= amount);
        address bankBefore;
        try c.bank() returns (address __r) { bankBefore = __r; } catch { return; }
        uint totalBefore = address(c).balance + c.bank().balance;
        bool reverted;
        try c.play{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }
        address bankAfter;
        try c.bank() returns (address __r) { bankAfter = __r; } catch { return; }
        uint totalAfter = address(c).balance + c.bank().balance;
        assertTrue(!reverted || (bankAfter == bankBefore && totalAfter >= totalBefore));
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
